import React, { Component } from 'react'
import { connect } from 'react-redux'
import { injectIntl } from 'react-intl'
import { Row, Col, Form, Button, Alert, notification, Modal } from 'antd'
import IntlMessages from '../../../../../components/utility/intlMessages'
import policyAction from '../../../../../redux/policy/actions'
import CircularLoader from '../../../../../components/CircularLoader'
import queryString from 'query-string'
import { ContainerLayout, CustomButton, FlexContainer, ModalContainer } from './index.style'
import validator from '../../../../../helpers/validator'
import { get } from 'lodash'
import { getFormItems } from '../../../../../components/utility/formItems'
import EndorseWelcome from '../ThankYouComponent'
import VietnamEndorseWelcome from '../VeitnamThankYou'
import { ERROR_STRINGS } from '../../../../../constants/lang'

const { resetReduxPolicy, tokenizedDetailEndorsement, unAuthorisedEndorsement } = policyAction

class FormContainer extends Component {
  constructor (props) {
    super(props)
    this.state = {
      internalID: '',
      token: '',
      serielNoModel: false
    }
  }

  componentDidMount () {
    const { id } = this.props
    const internalId = get(id, 'match.params.id')
    const tokenObject = get(id, 'location.search', '')
    if (tokenObject) {
      const token = get(queryString.parse(tokenObject), 'token', '')
      if (token && internalId) {
        this.setState({
          internalId: internalId,
          token: token
        })
        this.props.tokenizedDetailEndorsement({
          query: {
            id: internalId,
            token: token
          }
        })
      }
    }
  }

  componentWillReceiveProps (nextProps) {
    const { policyEndorsementError, policyEndorsement, policyEndorsementMessage, type } = nextProps
    if (policyEndorsementMessage !== '' && policyEndorsementMessage !== 'success') {
      const errorData = get(policyEndorsement, 'error', '')
      if (!policyEndorsementError && (errorData && errorData !== 'success')) {
        if (Array.isArray(errorData)) {
          errorData.forEach(item => {
            if (get(item, 'key', '')) {
              if (item.key === 'serial_number') {
                if (type === 'crack-screen') {
                  this.props.form.setFields({
                    [item.key]: {
                      value: item.val,
                      errors: [new Error(this.intlText({ id: 'Nomor IMEI sudah memiliki polis aktif' }))]
                    }
                  })
                }
                if (type === 'mobile-insurance') {
                  this.props.form.setFields({
                    [item.key]: {
                      value: item.val,
                      errors: [new Error(this.intlText({ id: 'Silakan masukkan nomor seri yang valid' }))]
                    }
                  })
                }
              } else {
                this.props.form.setFields({
                  [item.key]: {
                    value: item.val,
                    errors: [new Error(this.intlText({ id: item.err }))]
                  }
                })
              }
            } else {
              notification['error']({
                message: this.intlText({ id: 'Error' }),
                description: this.intlText({ id: item.err })
              })
            }
          })
          this.props.resetReduxPolicy(['authorizedEndorsementDataMessage'])
        } else {
          notification['error']({
            message: this.intlText({ id: 'Error' }),
            description: this.intlText({ id: errorData })
          })
          this.props.resetReduxPolicy(['authorizedEndorsementDataMessage'])
        }
      }
    }
  }

  intlText = (messageObj = { id: ' ' }) => {
    return this.props.intl.formatMessage(messageObj)
  }

  async validateForm () {
    return new Promise((resolve) => {
      this.props.form.validateFields((error) => {
        resolve(!error)
      })
    })
  }

  showErrorMessage = () => {
    return <Alert
      message={<IntlMessages id={ERROR_STRINGS.error} />}
      description={<IntlMessages id={ERROR_STRINGS.serverError} />}
      type='error'
    />
  }

  finalSubmit = async (e) => {
    e.preventDefault()
    const { internalId, token } = this.state
    const { form } = this.props
    const valid = await this.validateForm()
    if (!valid) {
      return
    }
    const formBody = form.getFieldsValue()

    const payload = {
      ...formBody
    }
    this.props.unAuthorisedEndorsement({
      query: {
        internal_id: internalId,
        token: token
      },
      body: payload
    })
  }

  handleModelOpen = () => {
    this.setState({ serielNoModel: true })
  }

  handleModelClose = () => {
    this.setState({ serielNoModel: false })
  }

  render () {
    const {
      getPolicyEndorsementDetailResult,
      policyEndorsementDetailLoading,
      policyEndorsementDetailError,
      policyEndorsementLoading,
      policyEndorsementMessage,
      type,
      header,
      subheading,
      vietnamProduct
    } = this.props
    let secondInputHeading = ''
    switch (type) {
      case 'mobile-insurance':
        // const categoryName = get(getPolicyEndorsementDetailResult, 'Request.category')
        // if (categoryName === 'Tablets' || categoryName === 'Mobile Phones') {
        //   secondInputHeading = 'Nomor IMEI / Nomor Serial'
        // } else {
        //   secondInputHeading = 'Nomor IMEI / Nomor Serial'
        // }
        secondInputHeading = vietnamProduct
          ? 'Số IMEI / Số SERI'
          : 'Nomor IMEI / Nomor Serial'
        break
      case 'crack-screen':
        secondInputHeading = 'Nomor IMEI'
        break
      default: return new Error()
    }

    const inputLabel = vietnamProduct ? 'Họ và tên' : 'Nama lengkap'

    const isSuccessFulEndorse = (policyEndorsementMessage === 'success') || get(getPolicyEndorsementDetailResult, 'EndorsementStatus') === 'SUCCESS'
    const userEmail = get(getPolicyEndorsementDetailResult, 'Email')
    return (
      <ContainerLayout>
        {isSuccessFulEndorse ? (
          vietnamProduct ? <VietnamEndorseWelcome userEmail={userEmail} /> : <EndorseWelcome />
        ) : policyEndorsementDetailError ? (
          this.showErrorMessage()
        ) : (
          <CircularLoader
            isSpining={
              policyEndorsementDetailLoading || policyEndorsementLoading
            }
          >
            <FlexContainer>
              <Form onSubmit={this.finalSubmit}>
                <Row type='flex' align='middle'>
                  <Col
                    xs={24}
                    sm={24}
                    md={12}
                    lg={12}
                    xl={12}
                    className='padding-24'
                  >
                    <img
                      src='https://pp-img-prod.s3.ap-southeast-3.amazonaws.com/policies/shopee/shopee-gadget-endorsement-image.png'
                      alt='shopee-gadget-banner'
                      width='100%'
                    />
                  </Col>
                  <Col
                    xs={24}
                    sm={24}
                    md={12}
                    lg={12}
                    xl={12}
                    className='padding-24'
                  >
                    <Row type='flex'>
                      <Col span={24}>
                        <h3 className='form-heading'>
                          <b>
                            <IntlMessages id={header} />
                          </b>
                        </h3>
                        <p className='form-subheading'>
                          <IntlMessages id={subheading} />
                        </p>
                      </Col>
                      <Col span={24}>
                        <Form.Item>
                          {getFormItems.call(this, {
                            formName: 'name',
                            type: 'alphanumericFloating',
                            label: inputLabel,
                            required: true,
                            validator: validator.checkValidator
                          })}
                        </Form.Item>
                      </Col>
                      <Col span={24}>
                        <Form.Item>
                          {getFormItems.call(this, {
                            formName: 'serial_number',
                            type: 'alphanumericFloating',
                            label: secondInputHeading,
                            required: true,
                            validator: validator.shopeeVnSerialNoValidator
                          })}
                        </Form.Item>
                      </Col>
                      <Col span={24}>
                        {vietnamProduct ? (
                          <React.Fragment>
                            <p>
                              <IntlMessages id='*Để kiểm tra số IMEI trên' />&nbsp;
                              <b><IntlMessages id='HP / thiết bị di động:' /></b> <br />
                              <IntlMessages id='Vui lòng bấm' />&nbsp;
                              <span className='theme-color'>
                                <IntlMessages id='*#06# số' />&nbsp;
                              </span>
                              <IntlMessages id='IMEI sẽ hiện ra màn hình.Nếu thiết bị của bạn có 2 dãy số IMEI,
  bạn vui lòng nhập dãy số IMEI đầu tiên để kích hoạt hợp đồng bảo hiểm.' />
                            </p>
                            <p>
                              <IntlMessages id='*Để kiểm tra số seri trên' />&nbsp;
                              <b><IntlMessages id='HP / thiết bị di động:' /></b> <br />
                              <span
                                onClick={this.handleModelOpen}
                                className='theme-color link'
                              >
                                <IntlMessages id='Cách kiểm tra số seri' />
                              </span>
                            </p>
                          </React.Fragment>
                        ) : (
                          <React.Fragment>
                            <p>
                              *Nomor IMEI berlaku untuk <b>HP / Smartphone:</b>{' '}
                              <br />
                              <span className='theme-color'>
                                Ketik *#06# pada layar panggilan
                              </span>{' '}
                              untuk cek Nomor IMEI
                            </p>
                            <p>
                              *Nomor Serial berlaku untuk produk selain{' '}
                              <b>HP / Smartphone:</b> <br />
                              <span
                                onClick={this.handleModelOpen}
                                className='theme-color link'
                              >
                                Lihat Cara Menemukan Nomor Serial
                              </span>
                            </p>
                          </React.Fragment>
                        )}
                      </Col>
                      <Col span={24}>
                        <CustomButton
                          className='theme-button'
                          htmlType='submit'
                        >
                          <IntlMessages id={vietnamProduct ? 'Gửi' : 'Kirim'} />
                        </CustomButton>
                      </Col>
                    </Row>
                  </Col>
                </Row>
              </Form>
            </FlexContainer>
            <Modal
              title={this.intlText({ id: 'Hướng dẫn cách tìm số SERI' })}
              visible={this.state.serielNoModel}
              onOk={this.handleModelClose}
              onCancel={this.handleModelClose}
              footer={null}
              centered
              wrapClassName='shopee-gadget-model'
            >
              <ModalContainer>
                {vietnamProduct ? (
                  <h4 className='modal-heading'>
                    <IntlMessages id='Số seri thể hiện trên vỏ hộp sản phẩm HP/thiết bị di động.' />
                  </h4>
                ) : (
                  <h4 className='theme-color'>
                    Nomor Serial berlaku untuk produk selain HP / Smartphone
                  </h4>
                )}

                {vietnamProduct ? (
                  <p>
                    <IntlMessages id='Bạn có thể tìm số seri ở mặt sau hộp của sản phẩm thiết bị điện tử hoặc máy tính bảng. hình dáng nhận dạng giống như miếng nhãn dán .Ví dụ hình ảnh như bên dưới.' />
                  </p>
                ) : (
                  <p>
                    Nomor serial gadget dapat Anda temukan di bagian belakang
                    kotak gadget Anda. Umumnya berbentuk seperti tempelan stiker
                    seperti contoh gambar dibawah.
                  </p>
                )}
                <div>
                  <img
                    src='https://pp-img-prod.s3.ap-southeast-3.amazonaws.com/policies/shopee/shopee-gadget-seriel-no-example.png'
                    alt='seriel-no-exaple'
                    width='100%'
                  />
                </div>
                <br />
                <br />
                <div style={{ textAlign: 'center' }}>
                  <Button
                    className='action-button'
                    onClick={this.handleModelClose}
                  >
                    {vietnamProduct ? 'Trở lại' : 'Kembali'}
                  </Button>
                </div>
              </ModalContainer>
            </Modal>
          </CircularLoader>
        )}
      </ContainerLayout>
    )
  }
}

FormContainer.defaultProps = {
  policyEndorsementLoading: false,
  policyEndorsementError: false,
  policyEndorsementDetailLoading: false,
  policyEndorsementDetailError: false
}
const ShopeeEndorsementWrapped = Form.create()(FormContainer)
export default connect(
  state => ({
    getPolicyEndorsementDetailResult: state.Policy.tokenisedEndorsementDetail,
    policyEndorsementDetailLoading: state.Loading.TOKENIZED_ENDORSEMENT_DETAIL,
    policyEndorsementDetailError: state.Error.TOKENIZED_ENDORSEMENT_DETAIL,
    policyEndorsement: state.Policy.authorizedEndorsementData,
    policyEndorsementMessage: state.Policy.authorizedEndorsementDataMessage,
    policyEndorsementLoading: state.Loading.UNAUTHORIZED_ENDORSEMENT,
    policyEndorsementError: state.Error.UNAUTHORIZED_ENDORSEMENT
  }),
  {
    resetReduxPolicy, tokenizedDetailEndorsement, unAuthorisedEndorsement
  }
)(injectIntl(ShopeeEndorsementWrapped))
